SELECT 'request_ranges event ids', count(*) FROM main.request_ranges rr JOIN pre.request_ranges old ON old.request_id=rr.request_id AND old.start_date=rr.start_date JOIN pre.requests r ON r.id=rr.request_id WHERE rr.calendar_event_id <> CASE WHEN old.calendar_event_id='' AND old.start_date=(SELECT min(x.start_date) FROM pre.request_ranges x WHERE x.request_id=old.request_id) AND r.calendar_event_id<>'' THEN r.calendar_event_id ELSE old.calendar_event_id END;
